async function getReview(c: Context, v: any) {
  const actor = await actorFor(c.userId); const w = await workspace(actor);
  const e = employeeFor(c, v.employee || 'me');
  let cycles = w.cycles.filter(x => !v.cycle || x.id === v.cycle || x.name.toLowerCase() === v.cycle.toLowerCase());
  if (v.cycle && !cycles.length) cycles = w.cycles.filter(x => x.name.toLowerCase().includes(v.cycle.toLowerCase()));
  if (v.cycle) ensure(cycles.length === 1, 'Specify one exact cycle name or ID.');
  cycles.sort((a, b) => Number(b.status === 'ACTIVE') - Number(a.status === 'ACTIVE') || b.createdAt.localeCompare(a.createdAt));
  const match = cycles.map(cycle => w.reviews.find(r => r.cycleId === cycle.id && r.employeeId === e.id)).find(Boolean);
  ensure(match, 'No launched review matches this employee and cycle.');
  return { actor, review: await reviewDetails(actor, match.id), employee: e };
}
function reviewResult(r: any): Result {
  return { message: `${r.employee.name}: ${r.cycle.name}. ${r.closedAt ? 'Closed' : r.manager.sharedAt ? 'Manager assessment shared' : r.self.sharedAt ? 'Waiting for manager assessment' : 'Self-assessment in progress'}.`, recordId: r.id, selectedEmployeeId: r.employeeId,
    cards: [{ title: 'Review progress', values: [{ label: 'Goals', value: String(r.goals.length) }, { label: 'Progress', value: `${r.progress}%` }, { label: 'Score', value: r.manager.sharedAt ? String(r.finalScore ?? r.scores?.total ?? '—') : 'Not shared' }, { label: 'Manager', value: r.employee.managerName }] }],
    table: rowsTable(['Goal', 'ID', 'Progress', 'Weight', 'Milestones'], r.goals.map((g: any) => [g.title, g.id, `${g.progress}%`, `${g.weight}%`, g.milestones.map((m: any) => `${m.title} (${m.id})${m.complete ? ' ✓' : ''}`).join('; ')])),
    links: [{ label: 'Open this review', path: `/performance?review=${encodeURIComponent(r.id)}#goals` }] };
}
async function listMaster(c: Context, resource: string) { return await api(c, 'GET', `/api/eim/${resource}`) as any[]; }
function resolveMaster(rows: any[], query: string, label: string) {
  const exact = rows.filter(r => r.id === query || r.name?.toLowerCase() === query.toLowerCase() || r.code?.toLowerCase() === query.toLowerCase());
  const found = exact.length ? exact : closest(rows, query, r => [r.name, r.code]);
  ensure(found.length === 1, `Use an exact ${label} name or ID. ${found.length > 1 ? 'More than one record matches.' : 'No match was found.'}`); return found[0];
}
